function eligibilityFields(value={},groups=[]){return `<div class="form-grid eligibility-fields">${selectfield('最低等级','min_level',[['','不限'],...levelOptions],value.min_level??'')}${selectfield('最高等级','max_level',[['','不限'],...levelOptions],value.max_level??'')}<fieldset class="field full group-checks"><legend>允许报名的组别</legend><div class="checks">${groups.length?groups.map(group=>`<label class="check-label"><input type="checkbox" name="allowed_group_ids" value="${attr(group.id)}"${(value.allowed_group_ids||[]).map(String).includes(String(group.id))?' checked':''}>${e(group.name)}</label>`).join(''):'<span class="muted">尚未设置会员组别</span>'}</div><small>不选择则不限组别。</small></fieldset></div>`;}
function eligibilityData(data){const min_level=nullableLevel(data.get('min_level')),max_level=nullableLevel(data.get('max_level'));if(min_level!==null&&max_level!==null&&min_level>max_level)throw new Error('最低等级不能高于最高等级。');return {min_level,max_level,allowed_group_ids:data.getAll('allowed_group_ids').map(Number)};}
