const beijingTime = value => {if(!value)return '';const text=String(value);if(!/(Z|[+-]\d{2}:?\d{2})$/i.test(text))return text.replace('T',' ').slice(0,16);const date=new Date(text);if(Number.isNaN(date.getTime()))return text.replace('T',' ').slice(0,16);const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date);return parts.replace(',', '').slice(0,16);};
