const safeUrl = value => { try { const u=new URL(String(value),location.origin); return ['http:','https:'].includes(u.protocol) && !u.username && !u.password ? u.href : ''; } catch{return '';} };
const filesSize = value => num(value)>1048576 ? `${(num(value)/1048576).toFixed(1)} MB` : `${Math.ceil(num(value)/1024)} KB`;
