function imageMarkup(url,label,cls=''){const safe=safeUrl(url);if(!safe)return '';const parsed=new URL(safe);const protectedPath=parsed.origin===location.origin&&/^\/api\/media\/[^/]+\/download$/.test(parsed.pathname);return `<img ${protectedPath?`data-media-url="${attr(parsed.pathname)}"`:`src="${attr(safe)}"`} alt="${attr(label)}" class="${attr(cls)}" loading="lazy" referrerpolicy="no-referrer">`;}
async function hydrateImages(root){const epoch=state.epoch,view=state.viewEpoch;const images=$$('img[data-media-url]:not([data-fetching])',root);await Promise.allSettled(images.map(async img=>{img.dataset.fetching='1';try{const blob=await api(img.dataset.mediaUrl,{blob:true});if(epoch!==state.epoch||view!==state.viewEpoch||!img.isConnected)return;const url=URL.createObjectURL(blob);mediaUrls.add(url);img.src=url;}catch(error){if(img.isConnected){img.alt+='（图片暂不可读取）';img.title=error.message;}}}));}
