const state={workspace:{},venueSelections:{},channels:[],authed:false,csrfToken:'',bots:[],botId:null,venues:[],venueId:null,platformAdmin:false,config:{},route:'dashboard',epoch:0,viewEpoch:0,controllers:new Set(),page:{},formats:[],composer:[],simTurns:[]};

class ApiError extends Error { constructor(message,status){super(message);this.status=status;} }
async function api(path,{method='GET',body,platform=false,botId=null,blob=false}={}){
  if(!path.startsWith('/api/')) throw new Error('请求地址无效');
  const headers={'X-CSRF-Token':state.csrfToken};
  if(botId) headers['X-Bot-ID']=String(botId);
  if(body && !(body instanceof FormData)) headers['Content-Type']='application/json';
  const controller=new AbortController();
  if(method==='GET') state.controllers.add(controller);
  let response;
  try {response=await fetch(path,{method,headers,body:body instanceof FormData?body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal,credentials:'same-origin',cache:'no-store'});}
  catch(error){if(error.name==='AbortError') throw error; throw new ApiError('无法连接服务，请检查网络后重试。',0);}
  finally{state.controllers.delete(controller);}
  if(!response.ok){
    let detail;try{const data=await response.json();detail=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail??data.error??'');}catch{detail='';}
    if(response.status===401 && state.authed){clearSession(false);}
    throw new ApiError(detail||({401:'管理凭据已失效，请重新登录。',403:'当前身份没有操作权限。',404:'未找到对应数据或接口。',409:'数据已更新，请刷新后重试。'}[response.status]||`请求失败（${response.status}）`),response.status);
  }
  if(blob) return response.blob();
  if(response.status===204) return {};
  return response.json();
}
const query = (path,params={}) => `${path}?${new URLSearchParams(Object.entries(params).filter(([,v])=>v!==undefined&&v!==null&&v!=='')).toString()}`;
const venueQuery = (path,params={}) => query(path,{venue_id:state.venueId,...params});
function resetContext(){state.epoch++;state.viewEpoch++;state.controllers.forEach(c=>c.abort());state.controllers.clear();clearMediaUrls();state.page={};state.composer=[];state.simTurns=[];state.formats=[];closeModal();}
function toast(message,error=false){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.innerHTML=`${icon(error?'alert':'check')}<span>${e(message)}</span><button aria-label="关闭通知">×</button>`;node.querySelector('button').onclick=()=>node.remove();$('#toasts').append(node);setTimeout(()=>node.remove(),error?12000:6000);}
function showError(error){if(error.name!=='AbortError')toast(error.message||String(error),true);}
function loading(label='正在读取数据'){return `<div class="loading" role="status"><span class="spinner"></span>${e(label)}</div>`;}
function showPageError(error){$('#main').innerHTML=`<div class="error-block">${icon('alert')}<div><h3>暂时无法打开此页面</h3><p>${e(error.message)}</p><div class="actions" style="margin-top:15px">${btn('重新加载','refresh','primary')}${btn('机器人配置','go','', 'data-route="bots"')}</div></div></div>`;}
function openModal(title,content,wide=false,subtitle=''){const el=$('#modal');setMobileNavigation(false,false);el.classList.toggle('wide',wide);el.innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button class="modal-close" data-action="modal-close" aria-label="关闭对话框">×</button></div><div class="modal-body">${content}</div>`;if(!el.open)el.showModal();syncOverlayLock();hydrateImages(el);return el;}
function closeModal(){clearTimeout(state.connectionTimer);const el=$('#modal');if(el?.open)el.close();if(el)el.innerHTML='';syncOverlayLock();}
let navigationReturnFocus=null,overlayScrollY=null;
const mobileNavigation=()=>typeof window!=='undefined'&&window.matchMedia('(max-width: 950px)').matches;
function syncOverlayLock(){
  if(typeof document==='undefined'||!document.body)return;
  const locked=Boolean($('.shell')?.classList.contains('nav-open')||$('#modal')?.open);
  if(locked&&overlayScrollY===null){overlayScrollY=window.scrollY||0;document.body.style.setProperty('--overlay-top',`-${overlayScrollY}px`);document.body.classList.add('overlay-open');}
  else if(!locked&&overlayScrollY!==null){const y=overlayScrollY;overlayScrollY=null;document.body.classList.remove('overlay-open');document.body.style.removeProperty('--overlay-top');window.scrollTo({top:y,left:0,behavior:'instant'});}
}
function setMobileNavigation(open,restoreFocus=true){
  const shell=$('.shell'),sidebar=$('#primary-navigation');if(!shell||!sidebar){syncOverlayLock();return;}
  const mobile=mobileNavigation(),wasOpen=shell.classList.contains('nav-open');open=Boolean(open&&mobile);
  if(open&&!wasOpen)navigationReturnFocus=document.activeElement;
  shell.classList.toggle('nav-open',open);sidebar.inert=mobile&&!open;
  sidebar.setAttribute('aria-hidden',String(mobile&&!open));
  if(open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');}
  else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');}
  const workspace=$('.workspace');if(workspace)workspace.inert=open;
  const backdrop=$('.nav-backdrop');if(backdrop)backdrop.hidden=!open;
  const toggle=$('.menu-toggle');if(toggle){toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'收起导航':'展开导航');}
  syncOverlayLock();
  if(open&&!wasOpen)($('.nav-close')||sidebar).focus();
  else if(wasOpen&&restoreFocus){const target=!mobile?$('#main'):(navigationReturnFocus?.isConnected?navigationReturnFocus:toggle);if(target)target.focus();}
  if(!open)navigationReturnFocus=null;
}
function handleNavigationKey(event){
  if(!$('.shell')?.classList.contains('nav-open'))return;
  if(event.key==='Escape'){event.preventDefault();setMobileNavigation(false);return;}
  if(event.key!=='Tab')return;
  const items=$$('a[href],button:not([disabled]),[tabindex="0"]',$('#primary-navigation')).filter(el=>!el.hidden);
  if(!items.length)return;const first=items[0],last=items[items.length-1];
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
}
function enhanceScrollRegions(root=document){
  $$('.table-wrap,.calendar-scroll',root).forEach(region=>{
    const overflowing=region.scrollWidth>region.clientWidth+1;region.dataset.overflow=String(overflowing);
    if(overflowing){region.setAttribute('tabindex','0');region.setAttribute('role','region');region.setAttribute('aria-label',region.classList.contains('calendar-scroll')?'活动日历，左右滑动查看更多日期':'数据表格，左右滑动查看完整内容');}
    else{region.removeAttribute('tabindex');region.removeAttribute('role');region.removeAttribute('aria-label');}
  });
}
function installResponsiveUI(){
  let frame=0;const refresh=()=>{if(frame)return;frame=requestAnimationFrame(()=>{frame=0;enhanceScrollRegions();});};
  if(typeof MutationObserver!=='undefined'){const observer=new MutationObserver(refresh);observer.observe($('#app'),{childList:true,subtree:true});observer.observe($('#modal'),{childList:true,subtree:true});}
  window.addEventListener('resize',()=>{setMobileNavigation(false);refresh();});
  document.addEventListener('keydown',handleNavigationKey);
  $('#modal').addEventListener('close',syncOverlayLock);
  $('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
  refresh();
}
function bindForm(id,callback){const form=document.getElementById(id);form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const epoch=state.epoch;const submit=$('[type=submit]',form);const error=$('.inline-error',form);if(error)error.textContent='';submit.disabled=true;const oldText=submit.textContent;submit.textContent='正在保存…';try{await callback(new FormData(form),form,epoch);}catch(err){if(err.name!=='AbortError'&&epoch===state.epoch){if(error)error.textContent=err.message;else showError(err);}}finally{if(form.isConnected){submit.disabled=false;submit.textContent=submit.dataset.idleLabel||oldText;}}});}
async function download(path,filename){const blob=await api(path,{blob:true});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

// Escaped Markdown subset; raw HTML and arbitrary protocols are never interpreted.
function markdown(value){
  const inline=source=>{
    const tokens=[];
    let text=String(source).replace(/<at\s+user_id=["'][^"']+["']\s*><\/at>/g,'@成员').replace(/!?\[([^\]\n]*)\]\(([^)\s]+)\)/g,(whole,label,url)=>{
      const safe=safeUrl(url);if(!safe)return label;const idx=tokens.length;
      const parsed=new URL(safe),protectedFile=parsed.origin===location.origin&&parsed.pathname.match(/^\/api\/media\/([^/]+)\/download$/);
      tokens.push(whole[0]==='!'?imageMarkup(safe,label):protectedFile?`<a href="#" data-action="media-download" data-id="${attr(protectedFile[1])}" data-name="${attr(label)}">${e(label)}</a>`:`<a href="${attr(safe)}" target="_blank" rel="noopener noreferrer">${e(label)}</a>`);
      return `\u0001${idx}\u0002`;
    });
    text=e(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
    text=text.replace(/&lt;font color=(?:&#39;|&quot;)(#[0-9a-f]{6})(?:&#39;|&quot;)&gt;(.*?)&lt;\/font&gt;/gi,'<span style="color:$1">$2</span>');
    return text.replace(/\u0001(\d+)\u0002/g,(_,i)=>tokens[Number(i)]||'');
  };
  const lines=String(value||'').split('\n'),parts=[];
  const cells=line=>line.trim().replace(/^\|/,'').replace(/\|$/,'').split(/(?<!\\)\|/).map(x=>x.trim().replace(/\\\|/g,'|'));
  for(let i=0;i<lines.length;i++){
    const line=lines[i];
    if(line.includes('|')&&i+1<lines.length&&cells(lines[i+1]).every(x=>/^:?-{3,}:?$/.test(x))){
      const header=cells(line),rows=[];i+=2;while(i<lines.length&&lines[i].includes('|')&&lines[i].trim()){rows.push(cells(lines[i]));i++;}i--;
      parts.push(`<div class="markdown-table"><table><thead><tr>${header.map(x=>`<th>${inline(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${header.map((_,col)=>`<td>${inline(row[col]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);continue;
    }
    if(/^###\s/.test(line))parts.push(`<h3>${inline(line.slice(4))}</h3>`);
    else if(/^##\s/.test(line))parts.push(`<h2>${inline(line.slice(3))}</h2>`);
    else if(/^#\s/.test(line))parts.push(`<h1>${inline(line.slice(2))}</h1>`);
    else if(/^>\s?/.test(line))parts.push(`<blockquote>${inline(line.replace(/^>\s?/,''))}</blockquote>`);
    else if(/^---+$/.test(line))parts.push('<hr>');
    else if(/^[-*]\s/.test(line))parts.push(`<p>• ${inline(line.slice(2))}</p>`);
    else parts.push(line?`<p>${inline(line)}</p>`:'');
  }
  return parts.join('');
}
