function renderLogin(message=''){setMobileNavigation(false,false);$('#app').innerHTML=`<div class="login gather-login is-loading" aria-busy="true"><section class="gather-login-title" aria-labelledby="gather-login-heading" inert><h1 id="gather-login-heading">聚场<span>GatherSpace</span></h1><p class="gather-login-functions">场地安排 · 活动报名 · 赛事组织 · 机器人与群</p></section><div class="gather-login-access" inert><form id="login-form" class="login-form"><h2>管理员登录</h2>${field('管理员密码','password','','password','required autocomplete="current-password" placeholder="输入管理员密码"')}<div class="inline-error" role="alert">${e(message)}</div><button type="submit" class="btn primary">${icon('lock')}登录工作台</button><p class="login-guide"><a href="/guide/admin">管理员操作说明</a></p></form></div></div>`;const login=$('.gather-login');if(window.GatherLogin)GatherLogin.mount(login);else{login.classList.replace('is-loading','is-ready');login.setAttribute('aria-busy','false');login.querySelectorAll('[inert]').forEach(el=>el.inert=false);}bindForm('login-form',async data=>{const result=await authApi('/auth/login',{password:data.get('password')});state.authed=true;state.csrfToken=result.csrf_token;await bootstrap();});}
async function authApi(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrfToken},credentials:'same-origin',cache:'no-store',...(body===undefined?{}:{body:JSON.stringify(body)})});let data={};try{data=await response.json();}catch{}if(!response.ok)throw new ApiError(data.detail||'登录失败，请重试。',response.status);return data;}
function clearSession(notify=true){resetContext();state.authed=false;state.csrfToken='';state.botId=null;state.venueId=null;state.bots=[];state.venues=[];state.config={};sessionStorage.removeItem('yuxie-admin-token');sessionStorage.removeItem('yuxie-bot-id');sessionStorage.removeItem('yuxie-venue-id');renderLogin();if(notify)toast('已退出登录。');}
