function passwordDialog(){openModal('修改管理员密码',`<form id="password-form">${field('当前密码','current_password','','password','required autocomplete="current-password"')}${field('新密码','new_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('再次输入新密码','confirm_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${formFooter('修改密码')}</form>`);bindForm('password-form',async(data)=>{if(data.get('new_password')!==data.get('confirm_password'))throw new Error('两次输入的新密码不一致。');await authApi('/auth/password',{current_password:data.get('current_password'),new_password:data.get('new_password')});clearSession(false);toast('密码已修改，请重新登录。');});}
