async function bootstrap(){const [result,workspace]=await Promise.all([api('/api/bots'),api('/api/workspace')]);state.bots=asList(result,'bots');state.workspace=workspace;state.platformAdmin=Boolean(result.is_platform_admin||result.role==='platform_admin'||state.bots.some(x=>x.role==='platform_admin'));const previous=sessionStorage.getItem('yuxie-bot-id');state.botId=state.bots.some(x=>String(x.id)===previous)?previous:state.bots[0]?.id??null;state.route=validRoute(location.hash.slice(1));await loadContext();renderShell();await renderRoute();}
