async function sessionConstraintsDialog(id){const session=state.page.registrations?.sessions?.find(x=>String(x.id)===String(id));if(!session)throw new Error('请重新打开活动场次。');const epoch=state.epoch;const groups=asList(await api('/api/member-groups'),'groups');if(epoch!==state.epoch)return;openModal('报名设置',`<form id="session-constraints-form"><p class="member-review-name">${e(state.page.day)} · ${e(session.name)}</p><div class="form-grid">${field('正式名额','capacity',session.capacity??8,'number','required min="1" max="1000"')}${field('替补名额','substitute_capacity',session.substitute_capacity??4,'number','required min="0" max="1000"')}</div>${eligibilityFields(session,groups)}${formFooter('保存报名设置')}</form>`);bindForm('session-constraints-form',async(data,form,context)=>{await api(`/api/sessions/${encodeURIComponent(id)}/constraints`,{method:'PATCH',body:{...eligibilityData(data),capacity:num(data.get('capacity')),substitute_capacity:num(data.get('substitute_capacity'))}});if(context===state.epoch){const day=state.page.day,selected=state.page.sessionId;closeModal();toast('报名设置已更新。');await openDay(day,selected);}});}
function drawChart(rows){const values=rows.slice(-14),max=Math.max(1,...values.map(x=>num(x.count??x.registrations)));if(!values.length)return empty('还没有统计数据','报名后可在这里查看每日变化。');return `<div class="chart" role="img" aria-label="${attr(values.map(x=>`${x.date}：${num(x.count??x.registrations)} 人`).join('；'))}">${values.map(x=>{const v=num(x.count??x.registrations);return `<div class="chart-bar" title="${attr(x.date)}：${v} 人"><span class="bar-number">${v}</span><div class="bar" style="height:${Math.max(2,v/max*100)}px"></div><span class="bar-label">${e(String(x.date).slice(5))}</span></div>`;}).join('')}</div>`;}
