async function renderTournaments(epoch){const daily=state.route==='daily',kind=daily?'daily':'large';const [data]=await Promise.all([api(venueQuery('/api/tournaments',{kind})),getFormats()]);if(!isCurrent(epoch))return;state.page.tournaments=asList(data,'tournaments').filter(t=>t.kind===kind);state.page.tournamentKind=kind;$('#main').innerHTML=head(daily?'每日趣味赛':'大型赛事',daily?'基于当日报名快速组赛，由发起人负责比赛。':'从赛事筹备到归档，分别管理人员、规则、赛程和通知。',btn(`${icon(daily?'plus':'trophy')}${daily?'发起每日趣味赛':'组织大型赛事'}`,'tournament-new','primary',`data-kind="${kind}"`),daily?'DAILY PLAY':'TOURNAMENT STUDIO')+`<section class="panel" style="margin-bottom:22px"><div class="toolbar"><div class="field"><label for="tournament-status">赛事状态</label><select id="tournament-status"><option value="">全部状态</option>${['draft','registration','closed','running','paused','completed','cancelled','archived'].map(v=>`<option value="${v}">${v==='cancelled'?'已关闭':STATUS[v][0]}</option>`).join('')}</select></div><div class="field grow"><label for="tournament-search">查找赛事</label><input id="tournament-search" placeholder="赛事名称、关键词或日期"></div></div></section><div id="tournament-list"></div>`;renderTournamentCards();['tournament-status','tournament-search'].forEach(id=>document.getElementById(id).addEventListener('input',renderTournamentCards));}
function renderTournamentCards(){const kind=$('#tournament-kind')?.value||'',status=$('#tournament-status')?.value||'',search=$('#tournament-search')?.value.trim().toLowerCase()||'';const rows=(state.page.tournaments||[]).filter(t=>(!kind||t.kind===kind)&&(!status||t.status===status)&&(!search||`${t.title} ${t.keyword||''} ${t.date}`.toLowerCase().includes(search)));$('#tournament-list').innerHTML=rows.length?`<div class="grid-3">${rows.map(t=>`<article class="tournament-card"><div class="card-body"><div class="card-top"><span class="badge outline ${t.kind==='large'?'blue':''}">${t.kind==='large'?'大型赛事':'每日策划'}</span>${badge(t.status==='cancelled'?'event_closed':t.status)}</div><h3>${e(t.title)}</h3><p class="muted" style="font-size:12px">${e(formatName(t.format))} · ${e(displayDate(t.date))}</p><div class="meta"><span>${icon('users')} ${nf(t.participant_count??t.participants_count??(Array.isArray(t.participants)?t.participants.filter(p=>p.status==='active').length:0))} 位参赛者</span><span>${nf(t.completed_matches??t.matches_completed)} / ${nf(t.match_count??t.total_matches)} 场</span></div>${t.keyword?`<p class="caption">报名关键词：${e(t.keyword)}报名</p>`:''}</div><div class="card-bottom"><span class="muted mono" style="font-size:10px">#${e(t.id)}</span>${btn('打开赛事 '+icon('arrow'),'tournament-open','small primary',`data-id="${attr(t.id)}"`)}</div></article>`).join('')}</div>`:empty('没有符合条件的赛事','调整筛选条件，或创建一场新比赛。',btn('创建赛事','tournament-new','primary',`data-kind="${state.page.tournamentKind||'large'}"`));}
