  openModal('编辑赛事配置',`<form id="event-edit-form"><div class="form-grid">${field('赛事名称','title',t.title,'text','required maxlength="120"')}${t.kind==='large'?field('报名关键词','keyword',t.keyword||'','text','required maxlength="40"'):''}${!drawn&&t.kind==='large'?field('报名开始时间','registration_open',localTimeInput(t.registration_open),'datetime-local','required')+field('报名结束时间','registration_close',localTimeInput(t.registration_close),'datetime-local','required'):''}${!drawn&&t.kind==='large'?selectfield('关联活动场次','session_id',[['','不关联固定活动'],...relatedSessions.map(s=>[s.id,`${s.name} ${s.start}–${s.end}`])],options.session_id||''):''}${!drawn?selectfield('比赛项目','discipline',[['doubles','双打'],['singles','单打']],options.discipline||'doubles')+selectfield('双打类别','doubles_category',doublesOptions,options.doubles_category||'open')+selectfield('分配方式','assignment_strategy',strategyOptions,options.assignment_strategy||'random')+field('分组数量','group_count',t.group_count||2,'number','required min="2" max="64"')+field('报名容量','capacity',options.capacity||128,'number','required min="2" max="2000"')+selectfield('比赛局数','best_of',[[1,'一局定胜负'],[3,'三局两胜']],options.best_of||1)+field('每局目标分','points',options.points||21,'number','required min="1" max="100"')+field('每局封顶分','cap',options.cap||30,'number','required min="1" max="200"')+field('领先分要求','win_by',options.win_by||2,'number','required min="1" max="10"')+field('每组晋级人数','advance_per_group',options.advance_per_group||2,'number','required min="1" max="16"'):''}${t.kind==='daily'?`<div class="field"><span class="field-label">比赛组织者</span><div class="identity-value">${e(options.organizer_name||'管理员')}</div></div>`:''}<div class="full">${textfield('规则备注','notes',options.notes||'','maxlength="2000"')}</div></div>${!drawn?`<section class="config-section"><h3>参赛条件</h3>${eligibilityFields(options.eligibility||{},groups)}</section>`:''}${formFooter('保存赛事配置')}</form>`,true);
