function renderMatchCards(){const t=state.page.tournament;const status=$('#match-status-filter')?.value||'';const search=$('#match-search')?.value.trim().toLowerCase()||'';const rows=(t.matches||[]).filter(m=>(!status||m.status===status)&&(!search||`${m.number} ${m.side_a_name||m.side_a?.name||''} ${m.side_b_name||m.side_b?.name||''}`.toLowerCase().includes(search)));$('#match-list').innerHTML=rows.length?`<div class="match-grid">${rows.map(m=>{const a=m.side_a_name||m.side_a?.name||sourceLabel(m.a_source),b=m.side_b_name||m.side_b?.name||sourceLabel(m.b_source);return `<article class="match-card"><div class="match-card-head"><span>第 ${nf(m.number)} 场 · ${e(stageName(m.stage))} ${m.round?`第 ${e(m.round)} 轮`:''}</span>${badge(m.status)}</div><div class="match-team ${m.winner&&m.winner===m.side_a?.id?'winner':''}"><span>${e(a)}</span><span class="match-score">${e((m.scores||[]).map(x=>x[0]).join(' / ')||'—')}</span></div><div class="match-team ${m.winner&&m.winner===m.side_b?.id?'winner':''}"><span>${e(b)}</span><span class="match-score">${e((m.scores||[]).map(x=>x[1]).join(' / ')||'—')}</span></div><div class="match-card-foot"><small>${m.scheduled_at?e(displayTime(m.scheduled_at)):'时间待编排'}${m.court?` · ${e(m.court)}`:''}</small>${t.status!=='cancelled'&&['ready','completed'].includes(m.status)?btn(m.status==='completed'?'修正比分':'记录比分','match-score',`small ${m.status==='ready'?'primary':''}`,`data-id="${attr(m.id)}"`):''}</div></article>`;}).join('')}</div>`:empty('暂无符合条件的对战','先完成报名与编排，或调整筛选条件。');}
function sourceLabel(source){return source?`第 ${source.match} 场${source.result==='loser'?'负者':'胜者'}`:'待确定';}
function scoreDialog(id){const t=state.page.tournament,m=t.matches.find(x=>String(x.id)===String(id));if(!m)return;const count=num(t.options?.best_of,1);openModal(`第 ${m.number} 场 · ${m.status==='completed'?'修正':'记录'}比分`,`<form id="score-form"><div class="notice" style="margin-bottom:20px"><strong>${e(m.side_a_name||m.side_a?.name)}</strong> 对 <strong>${e(m.side_b_name||m.side_b?.name)}</strong><br>目标 ${nf(t.options?.points||21)} 分，封顶 ${nf(t.options?.cap||30)} 分，领先 ${nf(t.options?.win_by||2)} 分。${count===3?' 三局两胜，未进行的第三局请留空。':''}</div>${Array.from({length:count},(_,i)=>`<div class="form-grid"><div class="full field-label" style="margin-bottom:7px">第 ${i+1} 局</div>${field(m.side_a_name||m.side_a?.name||'A 方',`a_${i}`,m.scores?.[i]?.[0]??'','number',`min="0" max="200" ${i===0?'required':''}`)}${field(m.side_b_name||m.side_b?.name||'B 方',`b_${i}`,m.scores?.[i]?.[1]??'','number',`min="0" max="200" ${i===0?'required':''}`)}</div>`).join('')}${formFooter(m.status==='completed'?'保存修正':'保存比分')}</form>`);bindForm('score-form',async(data,form,epoch)=>{const scores=[];let gap=false;for(let i=0;i<count;i++){const a=data.get(`a_${i}`),b=data.get(`b_${i}`);if(a===''&&b===''){gap=true;continue;}if(a===''||b==='')throw new Error(`请填写第 ${i+1} 局双方比分。`);if(gap)throw new Error('比分请按比赛顺序填写，不可跳过中间一局。');scores.push([num(a),num(b)]);}await api(`/api/tournaments/${encodeURIComponent(t.id)}/scores`,{method:'POST',body:{match_id:m.id,scores,expected_version:num(m.version)}});if(epoch===state.epoch){closeModal();toast('比分已记录，成绩已更新。');await openTournament(t.id,'matches');}});}
function matchSchedule(){const t=state.page.tournament;const rows=(t.matches||[]).filter(m=>!['completed','bye'].includes(m.status));if(!rows.length){toast('没有可编排的未完成比赛。',true);return;}openModal('编排比赛时间与球场',`<form id="schedule-form"><p class="muted" style="font-size:12px;margin-bottom:18px">按北京时间填写；球场可以写“1 号场”“东侧场”等现场标识。</p>${rows.map(m=>`<div class="form-grid schedule-row" data-id="${attr(m.id)}"><h3 class="full" style="font-size:13px;margin-bottom:12px">第 ${e(m.number)} 场 · ${e(m.side_a_name||m.side_a?.name||sourceLabel(m.a_source))} / ${e(m.side_b_name||m.side_b?.name||sourceLabel(m.b_source))}</h3><div class="field"><label>比赛时间<input type="datetime-local" name="scheduled_at" value="${attr(localTimeInput(m.scheduled_at))}"></label></div><div class="field"><label>球场标识<input name="court" value="${attr(m.court||'')}" maxlength="80"></label></div></div>`).join('')}${formFooter('保存赛程安排')}</form>`,true);bindForm('schedule-form',async(data,form,epoch)=>{const match_schedule=$$('.schedule-row',form).map(row=>({match_id:num(row.dataset.id),scheduled_at:isoTime($('[name=scheduled_at]',row).value),court:$('[name=court]',row).value.trim()}));await api(`/api/tournaments/${encodeURIComponent(t.id)}`,{method:'PATCH',body:{match_schedule}});if(epoch===state.epoch){closeModal();toast('赛程已保存。');await openTournament(t.id,'matches');}});}
async function tournamentEnroll(){const t=state.page.tournament,epoch=state.epoch;const members=asList(await api('/api/members?status=approved'),'members');if(epoch!==state.epoch)return;openModal('添加赛事参赛者',`<form id="enroll-form">${selectfield('参赛会员','user_id',members.map(m=>[m.user_id,`${memberName(m)} · ${levelName(m.level)}`]),'','required')}${field('本次新增同行人数','guests',0,'number','required min="0" max="20"')}${textfield('同行姓名','guest_names','','maxlength="1600" placeholder="例如：张三，李四"','填写姓名则按姓名追加；不填则按人数追加。已报名同行保留。')}${!members.length?'<div class="notice warning">暂无已审核会员。</div>':''}${formFooter('添加参赛者')}</form>`);bindForm('enroll-form',async(data,form,context)=>{const member=members.find(m=>String(m.user_id)===data.get('user_id'));if(!member)throw new Error('请选择已审核会员。');await api(`/api/tournaments/${encodeURIComponent(t.id)}/participants`,{method:'POST',body:{user_id:member.user_id,name:member.name,guests:guestNames(data.get('guest_names')).length||num(data.get('guests')),...(guestNames(data.get('guest_names')).length?{guest_names:guestNames(data.get('guest_names'))}:{})}});if(context===state.epoch){closeModal();toast('参赛者已加入。');await openTournament(t.id,'participants');}});}
async function tournamentNotify(){const t=state.page.tournament,epoch=state.epoch;const [allChannels,organization]=await Promise.all([loadChannels(),api(`/api/tournaments/${encodeURIComponent(t.id)}/organization`)]);const channels=allChannels.filter(c=>(t.kind==='daily'||channelSupportsBusiness(c,'large_events'))&&channelServesVenue(c,t.venue_id)&&(organization.channel_ids||[]).map(String).includes(String(c.id)));if(epoch!==state.epoch)return;openModal('发布赛事消息',`<form id="notify-form">${selectfield('消息内容','type',[['registration','报名通知与关键词'],['closed','报名结束通知'],['groups','随机分组结果'],['schedule','完整赛程'],['results','成绩与获胜者']],t.status==='completed'?'results':t.status==='registration'?'registration':'schedule')}${channelOptions(channels,organization.channel_ids||[])}<div id="event-destinations" class="notice" style="margin-bottom:18px">选择要通知的群。</div>${formFooter('发送赛事消息')}</form>`,true);const update=()=>{const ids=new FormData($('#notify-form')).getAll('channel_ids');$('#event-destinations').textContent=ids.length?`将发送至 ${selectedChannelGroups(channels,ids).length} 个群：${channelGroupSummary(channels,ids)}。同群的本次通知只发一次`:'尚未选择接收群。';};$('#notify-form').addEventListener('change',update);update();bindForm('notify-form',async(data,form,context)=>{const channel_ids=data.getAll('channel_ids');if(!channel_ids.length)throw new Error('至少选择一个接收群。');await api(`/api/tournaments/${encodeURIComponent(t.id)}/notify`,{method:'POST',body:{type:data.get('type'),channel_ids}});if(context===state.epoch){closeModal();toast(`赛事消息已加入 ${selectedChannelGroups(channels,channel_ids).length} 个群的发送队列。`);}});}
function attachmentCard(file){const url=safeUrl(file.url||file.public_url),imageFile=file.kind==='image'||String(file.content_type||file.mime_type||'').startsWith('image/');return `<article class="attachment">${imageFile&&url?imageMarkup(url,file.caption||file.name||'赛事照片'):`<div class="file-symbol">${icon(imageFile?'image':'file')}</div>`}<div class="attachment-info"><strong>${e(file.name||file.filename||`资料 ${file.id}`)}</strong><p>${e(file.caption||'')}</p><small>${filesSize(file.size)} · ${e(displayDate(file.created_at))}</small><div class="actions">${btn('下载','media-download','small',`data-id="${attr(file.id)}" data-name="${attr(file.name||file.filename||`资料-${file.id}`)}"`)}</div></div></article>`;}
async function renderMessages(epoch){const [result,allChannels]=await Promise.all([api('/api/messages'),loadChannels()]);if(!isCurrent(epoch))return;const channels=allChannels.filter(c=>channelSupportsBusiness(c,'messages'));state.page.messages=asList(result,'messages');state.composer=[];$('#main').innerHTML=head('消息中心','选择接收群，编辑文字、图片与附件，预览后发布。','','GROUP BROADCAST')+`${state.config.delivery_mode==='simulation'?'<div class="notice warning" style="margin-bottom:20px">当前为模拟发送模式：消息保存在本地队列，不会发送到真实群。</div>':''}<div class="stack"><section class="panel"><div class="panel-head"><div><h2>新建消息</h2><p>支持 Markdown；附件按平台支持能力展示为图片或下载链接。</p></div><span class="badge blue">管理员发布</span></div><div class="split-editor"><div><form id="composer-form">${channelOptions(channels)}${field('消息标题','title','','text','maxlength="120" placeholder="例如：本周羽球活动安排"')}<div class="field"><label for="composer-text">消息正文</label><div class="editor-tools"><button type="button" data-action="editor-insert" data-style="bold">加粗</button><button type="button" data-action="editor-insert" data-style="heading">小标题</button><button type="button" data-action="editor-insert" data-style="list">清单</button><button type="button" data-action="editor-insert" data-style="quote">提示</button><button type="button" data-action="editor-insert" data-style="divider">分隔线</button></div><textarea class="composer-text" name="text" id="composer-text" maxlength="20000" placeholder="把活动时间、地点和报名方式写清楚…"></textarea></div><div class="field"><label for="composer-files">添加图片或文件</label><input type="file" id="composer-files" multiple><small>支持 PNG/JPEG/WebP、PDF、文本/CSV、无宏 Office 文件，单个不超过 10 MiB。上传完成后可发送。</small></div><div id="composer-files-list" class="actions"></div><div class="inline-error" role="alert"></div><div class="form-footer">${btn('获取发送预览','message-preview')}<button type="submit" class="btn primary">${icon('send')}发布到群</button></div></form></div><div class="composer-preview"><div class="composer-preview-label">消息内容预览</div><div id="message-preview" class="preview"><p class="muted">从左侧开始编辑。</p></div><p class="caption">此处用于检查内容结构，客户端的字体、颜色和图片布局可能不同。</p></div></div></section>${panel('发送记录',messageHistory(state.page.messages),'“加入队列”不等于送达；以发送记录状态为准。',btn('刷新记录','message-history','small'))}</div>`;$('#composer-form').addEventListener('input',composerLocalPreview);$('#composer-files').addEventListener('change',uploadComposerFiles);bindForm('composer-form',async(data,form,epoch)=>{if(state.page.uploading)throw new Error('附件仍在上传，请稍候。');const payload=composerPayload();if(!payload.channel_ids.length)throw new Error('至少选择一个接收群。');if(!payload.text.trim()&&!payload.title.trim()&&!payload.media_ids.length)throw new Error('请填写文字或上传至少一个附件。');const result=await api('/api/messages/preview',{method:'POST',body:payload});if(epoch!==state.epoch)return;openModal('确认发布到群',`<p class="notice" style="margin-bottom:18px">将发送至 ${selectedChannelGroups(channels,payload.channel_ids).length} 个群：${e(channelGroupSummary(channels,payload.channel_ids))}。同群的本次通知只发一次。</p><div class="preview" style="min-height:0;margin-bottom:18px">${markdown(result.markdown)}</div><form id="send-confirm-form">${formFooter('确认发送')}</form>`,true);bindForm('send-confirm-form',async(_data,_form,context)=>{await api('/api/messages/send',{method:'POST',body:payload});if(context===state.epoch){closeModal();toast('消息已加入发送队列。');state.composer=[];form.reset();renderComposerFiles();composerLocalPreview();await refreshMessageHistory();}});});}
function composerPayload(){const form=$('#composer-form');return {title:form.elements.title.value.trim(),text:form.elements.text.value,media_ids:state.composer.map(f=>f.id),channel_ids:new FormData(form).getAll('channel_ids')};}
function composerLocalPreview(){if(!$('#composer-form'))return;const p=composerPayload();$('#message-preview').innerHTML=markdown(`${p.title?`## ${p.title}\n\n`:''}${p.text}`)||'<p class="muted">从左侧开始编辑。</p>';for(const f of state.composer){const n=document.createElement('p');n.innerHTML=f.kind==='image'&&safeUrl(f.url)?imageMarkup(f.url,f.name):`${icon('file')} ${e(f.name)} <small class="muted">${filesSize(f.size)}</small>`;$('#message-preview').append(n);}hydrateImages($('#message-preview'));}
function renderComposerFiles(){const root=$('#composer-files-list');if(root)root.innerHTML=state.composer.map(f=>`<span class="attachment-chip">${icon(f.kind==='image'?'image':'file')}${e(f.name)}<button type="button" aria-label="移除附件 ${attr(f.name)}" data-action="composer-remove" data-id="${attr(f.id)}">×</button></span>`).join('');}
async function uploadComposerFiles(event){const epoch=state.epoch;const view=state.viewEpoch;const files=[...event.target.files];const input=event.target;state.page.uploading=true;input.disabled=true;const submit=$('#composer-form [type=submit]');submit.disabled=true;try{for(const file of files){const data=new FormData();data.set('file',file);const result=await api('/api/media',{method:'POST',body:data});if(epoch!==state.epoch||view!==state.viewEpoch)return;state.composer.push(result.media||result);renderComposerFiles();composerLocalPreview();}if(files.length)toast(`${files.length} 个附件已上传。`);}catch(error){if(epoch===state.epoch&&view===state.viewEpoch)showError(error);}finally{if(epoch===state.epoch&&view===state.viewEpoch){state.page.uploading=false;input.disabled=false;input.value='';submit.disabled=false;}}}
function messageHistory(rows){return `<div id="message-history-body">${rows.length?`<div class="table-wrap"><table><thead><tr><th>消息</th><th>接收群</th><th>创建时间</th><th>发送状态</th><th>结果</th><th></th></tr></thead><tbody>${rows.map((m,index)=>`<tr><td class="name">${e(m.title||m.kind||m.type||'群消息')}<span class="sub">${e(String(m.text||m.markdown||m.body?.markdown?.text||'').slice(0,70))}</span></td><td>${e(m.channel_name||state.channels.find(c=>String(c.id)===String(m.channel_id))?.name||m.chat_id||'历史通道')}</td><td class="mono">${e(displayTime(m.created_at||m.time))}</td><td>${badge(m.status==='pending'?'queued':m.status)}</td><td class="muted">${e(m.error||m.last_error||m.result||'—')}</td><td>${btn('查看','message-detail','small',`data-index="${index}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有发送记录','选择群并发布消息，发送结果会在此逐群显示。')}</div>`;}
async function refreshMessageHistory(){const epoch=state.epoch;const result=await api('/api/messages');if(epoch!==state.epoch||!$('#message-history-body'))return;state.page.messages=asList(result,'messages');$('#message-history-body').outerHTML=messageHistory(state.page.messages);}
function insertEditor(style){const el=$('#composer-text');const start=el.selectionStart,end=el.selectionEnd;const selected=el.value.slice(start,end);const parts={bold:`**${selected||'重点内容'}**`,heading:`\n### ${selected||'小标题'}\n`,list:`\n- ${selected||'事项一'}\n- 事项二\n`,quote:`\n> ${selected||'温馨提醒'}\n`,divider:'\n\n---\n\n'};el.setRangeText(parts[style]||'',start,end,'end');el.focus();composerLocalPreview();}

async function renderSimulator(epoch){const channels=(await loadChannels()).filter(c=>isActive(c.active)&&c.receive_commands);if(!isCurrent(epoch))return;state.simTurns=[];$('#main').innerHTML=head('对话演练','用指定成员身份验证指令、引导和权限判断。','','CONVERSATION LAB')+`<div class="notice warning" style="margin-bottom:22px">演练不会向群里发送消息，但报名、取消和记分会更新俱乐部真实活动记录。</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>机器人对话</h2><p>选择会员身份发送指令。</p></div></div><div class="toolbar">${selectfield('演练群通道','sim_channel',channels.map(c=>[c.id,channelName(c)]),'','required')}<div class="field grow"><label for="sim-user">用户 ID</label><input id="sim-user" placeholder="填写要模拟的用户 ID" inputmode="numeric" required></div><div class="field"><label for="sim-name">显示姓名</label><input id="sim-name" value="测试成员" maxlength="80"></div></div><div class="simulation-chat" id="simulation-chat"><div class="chat-turn bot"><strong>准备好后，发送一句话。</strong><p class="muted" style="font-size:12px;margin-top:6px">从“帮助”或“身份”开始。</p></div></div><form id="sim-form"><div class="simulator-input"><label class="sr-only" for="sim-content">消息内容</label><input id="sim-content" name="content" class="control" required maxlength="4000" placeholder="例如：报名 接龙"><button class="btn primary" type="submit" aria-label="发送演练消息">${icon('send')}</button></div><div class="inline-error" style="padding:0 18px" role="alert"></div></form></section><div class="stack">${panel('常用指令',`<div class="panel-body"><div class="sample-commands">${['帮助','身份','注册','待审核','审核通过 申请12','审核拒绝 申请12','自评1级','报名','报名+2','报名，张三，李四','报名 接龙','取消报名','取消张三，李四','名单','我的统计','组织比赛','组织比赛 单打','组织比赛 混双','记录','我的对战历史','我的对战统计','积分赛','五人转','继续比赛',`${datePlus(1)} 18:00 报名`,'场地 1 名单'].map(text=>`<button data-action="sim-example" data-text="${attr(text)}">${e(text)}</button>`).join('')}</div><p class="caption">大型赛事发送“关键词报名”。记分示例：“周二双打，第2场21:19”。请替换为实际赛事名称；组织者或指定记分人员可以记分。</p></div>`)}${panel('每日比赛',`<div class="panel-body"><p>发送“组织比赛”查看当天人数和可选赛制，再选择比赛形式。</p><p class="caption">默认双打；需要单打时发送“组织比赛 单打”。</p></div>`)}</div></div>`;bindForm('sim-form',async(data,form,context)=>{const channel_id=$('#f-sim_channel').value;if(!channel_id)throw new Error('请先接入可接收指令的群通道。');const userId=$('#sim-user').value.trim();if(!userId)throw new Error('先填写要模拟的用户 ID。');const text=data.get('content').trim();if(!text)throw new Error('消息内容不能为空。');addChat('user',text);const result=await api('/api/simulator',{method:'POST',body:{channel_id,content:text,user_id:userId,name:$('#sim-name').value.trim()||'测试成员'}});if(context===state.epoch&&$('#simulation-chat')){addChat('bot',result.reply||'指令已处理，未返回文字。');form.reset();}});}

function addChat(role,text){const node=document.createElement('div');node.className=`chat-turn ${role}`;if(role==='bot')node.innerHTML=`<div class="preview">${markdown(text)}</div>`;else node.textContent=text;$('#simulation-chat').append(node);node.scrollIntoView({behavior:'smooth',block:'nearest'});}

function confirmAction(title,message,button,callback){openModal(title,`<form id="confirm-form"><p style="line-height:1.9;margin-bottom:20px">${e(message)}</p>${formFooter(button)}</form>`);bindForm('confirm-form',async(data,form,epoch)=>{await callback(epoch);});}
async function specialSlots(){return datePlanDialog();}

const TRANSITIONS={close:['关闭比赛','关闭后保留已记录的赛程与比分，无法继续该赛事。','关闭比赛'],open_registration:['开放报名','开放后，群成员可使用赛事关键词报名。','开放报名'],close_registration:['结束报名','结束后停止接收新参赛者，可以进行随机分组。','结束报名'],draw:['随机分组与编排','按已报名人员随机生成分组和对战表，结果将保存。开始记分后不能随意重新抽签。','生成对战表'],start:['开始比赛','开始后可依次登记比赛得分。','开始比赛'],pause:['暂停比赛','暂停后保存当前名单、对战与比分，之后可以继续。','暂停比赛'],resume:['继续比赛','从已经保存的赛程和比分继续。','继续比赛'],advance:['同分抽签并晋级','晋级边界选手的胜场、局净胜和分净胜全部相同。执行有记录的抽签决定出线顺序。','抽签并晋级'],archive:['归档赛事','保存完整赛果、流程和照片文件以供之后查询。','归档赛事']};
document.addEventListener('click',async event=>{
  const routeLink=event.target.closest('a[data-route]');if(routeLink){event.preventDefault();await navigate(routeLink.dataset.route);return;}
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;event.preventDefault();
  try{switch(action){
    case 'logout':await logout();break;
    case 'menu':setMobileNavigation(!$('.shell')?.classList.contains('nav-open'));break;
    case 'menu-close':setMobileNavigation(false);break;
    case 'modal-close':closeModal();break;
    case 'password-change':passwordDialog();break;
    case 'refresh':await renderRoute();break;
    case 'go':await navigate(target.dataset.route);break;
    case 'open-today':await openDay(today());break;
    case 'day-open':await openDay(target.dataset.date,target.dataset.session||'');break;
    case 'calendar-prev':case 'calendar-next':{const [y,m]=state.page.month.split('-').map(Number);const date=new Date(Date.UTC(y,m-1+(action==='calendar-next'?1:-1),1));await renderCalendar(++state.viewEpoch,date.toISOString().slice(0,7));$('#main').insertAdjacentHTML('afterbegin',sectionTabs('calendar'));break;}
    case 'calendar-today':await renderCalendar(++state.viewEpoch,today().slice(0,7));$('#main').insertAdjacentHTML('afterbegin',sectionTabs('calendar'));break;
    case 'role-new':grantRoleDialog();break;
    case 'role-edit':grantRoleDialog(target.dataset.userId);break;
    case 'member-notices':await identityNoticesDialog();break;
    case 'identity-notice-retry':await retryIdentityNotice(target.dataset.id);break;
    case 'channel-new':await channelDialog(target.dataset.botId);break;
    case 'channel-edit':await channelDialog(target.dataset.botId,target.dataset.id);break;
    case 'channel-toggle':await toggleBotChannel(target.dataset.botId,target.dataset.id,target.dataset.active==='true');break;
    case 'channel-remove':removeBotChannel(target.dataset.botId,target.dataset.id,target.dataset.name);break;
    case 'bot-help':await previewBotHelp(target.dataset.id);break;
    case 'bot-callback':await viewBotCallback(target.dataset.id);break;
    case 'imports-template':await download('/api/member-imports/template','会员预登记模板.csv');break;
    case 'imports-reset':resetImportPreview();$('#member-import-file')?.focus();break;
    case 'imports-refresh':await refreshImportRecords();break;
    case 'imports-reconcile':await reconcileImportedMembers();break;
    case 'imports-invite':await inviteImportedMembers();break;
    case 'profile-review':profileReviewDialog(Number(target.dataset.id));break;
    case 'member-pending':$('#member-status-filter').value='pending';renderMemberTable();break;
    case 'import-edit':editImportedRecord(target.dataset.id);break;
    case 'member-new':await memberDialog();break;
    case 'member-edit':await memberDialog(target.dataset.userId);break;
    case 'member-membership':await memberMembershipDialog(target.dataset.userId);break;
    case 'member-level':memberLevelDialog(target.dataset.userId);break;
    case 'member-groups':await memberGroupsDialog();break;
    case 'member-group-edit':renameMemberGroup(target.dataset.id);break;
    case 'session-constraints':await sessionConstraintsDialog(target.dataset.id);break;
    case 'registration-new':await newRegistration(target.dataset.date||state.page.day||today(),target.dataset.session||'',target.dataset.venue||'');break;
    case 'registration-cancel':{const id=target.dataset.id,date=state.page.day,session=target.closest('.activity-session')?.dataset.session||state.page.sessionId;confirmAction('取消报名',`将取消“${target.dataset.name}”的这条报名记录。历史记录会保留；同一用户的其他代报名记录不受此次操作影响。`,'确认取消',async epoch=>{await api(`/api/registrations/${encodeURIComponent(id)}`,{method:'DELETE'});if(epoch===state.epoch){closeModal();toast('报名已取消。');activityChanged();await refreshActivityCalendar();await openDay(date,session);}});break;}
    case 'registration-export':await download(query('/api/registrations/export',{venue_id:target.dataset.venue||state.venueId,date:target.dataset.date||'',session_id:target.dataset.session||''}),`报名记录-场地${target.dataset.venue||state.venueId}-${target.dataset.date||today()}.csv`);break;
    case 'slot-add':$('#slot-rows').insertAdjacentHTML('beforeend',slotRow({},$$('.rule-row').length));break;
    case 'slot-remove':target.closest('.rule-row').remove();break;
    case 'venue-new':editVenue();break;
    case 'venue-edit':editVenue(target.dataset.id);break;
    case 'venue-slots':resetContext();state.slotVenueFilter=target.dataset.id;await navigate('sessions');break;
    case 'bot-new':await editBotScope(null,{group_id:target.dataset.groupId||''});break;
    case 'group-new':await editGroup(null,target.dataset.botId);break;
    case 'group-edit':await editGroup(target.dataset.id);break;
    case 'group-delete':removeBotGroup(target.dataset.id);break;
    case 'connection-progress':await showConnectionProgress(target.dataset.botId,target.dataset.id);break;
    case 'channel-option':await toggleChannelOption(target.dataset.botId,target.dataset.id,target.dataset.key,target.dataset.active==='true');break;

    case 'special-slots':await specialSlots();break;
    case 'special-slot-add':$('#special-slot-rows').insertAdjacentHTML('beforeend',slotRow({},$$('#special-slot-rows .rule-row').length));break;
    case 'bot-edit':editBot(target.dataset.id);break;
    case 'bot-reminders':await revealBotSettings(target.dataset.id,'broadcast');break;
    case 'bot-delete':removeBot(target.dataset.id);break;
    case 'bot-switch':await navigate('bots');break;
    case 'copy-callback':{const el=$('#f-callback_url');try{await navigator.clipboard.writeText(el.value);toast('回调地址已复制。');}catch{el.focus();el.select();toast('已选中地址，请按 Ctrl+C 复制。');}break;}
    case 'tournament-new':await tournamentForm(target.dataset.kind||'large');break;
    case 'tournament-edit':await tournamentForm(state.page.tournament?.kind||'large',target.dataset.id);break;
    case 'tournament-open':await openTournament(target.dataset.id);break;
    case 'tournament-tab':await tournamentTab(target.dataset.tab);break;
    case 'tournament-action':{const id=target.dataset.id,transition=target.dataset.transition;const details=TRANSITIONS[transition];confirmAction(...details,async epoch=>{await api(`/api/tournaments/${encodeURIComponent(id)}/actions`,{method:'POST',body:{action:transition}});if(epoch===state.epoch){closeModal();toast(`${details[0]}已完成。`);await openTournament(id);}});break;}
    case 'tournament-entry-cancel':{const event=state.page.tournament,id=target.dataset.id;if(!event||!tournamentCanEditRegistrations(event))throw new Error('当前不能修改赛事报名。');confirmAction('取消赛事报名',`仅取消“${target.dataset.name}”的这条报名，其他参赛者和同行保留。`,'确认取消',async epoch=>{await api(`/api/tournaments/${encodeURIComponent(event.id)}/entries/${encodeURIComponent(id)}`,{method:'DELETE'});if(epoch===state.epoch){closeModal();toast('赛事报名已取消。');await openTournament(event.id,'participants');}});break;}
    case 'tournament-enroll':await tournamentEnroll();break;
    case 'tournament-notify':await tournamentNotify();break;
    case 'match-score':scoreDialog(target.dataset.id);break;
    case 'match-schedule':matchSchedule();break;
    case 'staff-add':$('#staff-rows').insertAdjacentHTML('beforeend',eventStaffRow());break;
    case 'staff-remove':target.closest('.staff-row').remove();break;
    case 'media-download':await download(`/api/media/${encodeURIComponent(target.dataset.id)}/download`,target.dataset.name);break;
    case 'editor-insert':insertEditor(target.dataset.style);break;
    case 'composer-remove':state.composer=state.composer.filter(x=>String(x.id)!==target.dataset.id);renderComposerFiles();composerLocalPreview();break;
    case 'message-preview':{if(state.page.uploading)throw new Error('附件仍在上传，请稍候。');const epoch=state.epoch,view=state.viewEpoch;target.disabled=true;try{const result=await api('/api/messages/preview',{method:'POST',body:composerPayload()});if(epoch===state.epoch&&view===state.viewEpoch){$('#message-preview').innerHTML=markdown(result.markdown);hydrateImages($('#message-preview'));}}finally{target.disabled=false;}break;}
    case 'message-history':await refreshMessageHistory();break;
    case 'message-detail':{const m=state.page.messages[num(target.dataset.index)];openModal('发送内容',`<div class="actions" style="margin-bottom:18px">${badge(m.status)}<span class="muted">${e(displayTime(m.created_at))}</span></div><div class="preview" style="min-height:0">${markdown(m.markdown||m.text||m.body?.markdown?.text||m.payload?.markdown?.text||'没有可展示的文字内容。')}</div>`,true);break;}
    case 'sim-example':$('#sim-content').value=target.dataset.text;$('#sim-content').focus();break;
  }}catch(error){showError(error);}
});
window.addEventListener('hashchange',()=>{if(state.authed)navigate(validRoute(location.hash.slice(1)));});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
installResponsiveUI();renderLogin();restoreSession();
